1	/**
2	 * Source versions of ABAP objects (SE38 / SE80 "Versions", Eclipse ADT
3	 * "Compare With → Revision").
4	 *
5	 * Primary path: the ADT revision feed of an object's source,
6	 *   GET <source uri>/versions            (Atom feed, one entry per version)
7	 *   GET <entry content uri>              (the source text of that version)
8	 * Fallback for systems without the feed: the version directory VRSD read
9	 * through ZMCP_ADT_DISPATCH TABLE_READ (list only — the version source then
10	 * needs a dispatcher action, not part of this module).
11	 */
12	
13	import type { IAbapConnection } from '@babamba2/mcp-abap-adt-interfaces';
14	import { XMLParser } from 'fast-xml-parser';
15	import { legacyTableRead } from './legacyTableRead';
16	import { resolveAdtUri } from './resolveAdtUri';
17	import { makeAdtRequest } from './utils';
18	
19	/** Object types whose source has versions. */
20	export const VERSIONED_TYPES = [
21	  'PROG/P',
22	  'PROG/I',
23	  'CLAS/OC',
24	  'INTF/OI',
25	  'FUGR/FF',
26	] as const;
27	
28	/** Class source parts that ADT versions one by one. */
29	export const CLASS_INCLUDES = [
30	  'main',
31	  'definitions',
32	  'implementations',
33	  'macros',
34	  'testclasses',
35	] as const;
36	
37	export interface VersionTarget {
38	  object_type: string;
39	  object_name: string;
40	  /** function group of a function module (FUGR/FF) */
41	  function_group?: string;
42	  /** class part (CLAS/OC); default main */
43	  class_include?: string;
44	}
45	
46	export interface ObjectVersion {
47	  /** version number as SAP shows it (00000 = the active / newest one in the feed) */
48	  version: string;
49	  /** ISO time of the version */
50	  date: string;
51	  author: string;
52	  /** transport request the version was created with, if any */
53	  transport: string;
54	  /** short text of the version (feed title), if any */
55	  title: string;
56	  /** ADT URI that returns this version's source; empty in the VRSD fallback */
57	  content_uri: string;
58	}
59	
60	/** Normalises the type the caller gave (PROG, CLAS, FUNC …) to an ADT type with a slash. */
61	export function normaliseType(t: string): string {
62	  const u = String(t ?? '')
63	    .toUpperCase()
64	    .trim();
65	  const map: Record<string, string> = {
66	    PROG: 'PROG/P',
67	    REPS: 'PROG/P',
68	    INCLUDE: 'PROG/I',
69	    PROGI: 'PROG/I',
70	    CLAS: 'CLAS/OC',
71	    INTF: 'INTF/OI',
72	    FUNC: 'FUGR/FF',
73	    FM: 'FUGR/FF',
74	  };
75	  return map[u] ?? u;
76	}
77	
78	/**
79	 * ADT URI of the version feed of one object's source.
80	 * @throws when the type has no versioned source or a needed parent is missing
81	 */
82	export function versionsUri(target: VersionTarget): string {
83	  const type = normaliseType(target.object_type);
84	  if (!(VERSIONED_TYPES as readonly string[]).includes(type)) {
85	    throw new Error(
86	      `object_type ${target.object_type} has no source versions here; use one of ${VERSIONED_TYPES.join(', ')}`,
87	    );
88	  }
89	  if (type === 'FUGR/FF' && !target.function_group) {
90	    throw new Error(
91	      'function_group is required for a function module (FUGR/FF)',
92	    );
93	  }
94	  const base = resolveAdtUri({
95	    name: target.object_name,
96	    type,
97	    parentName: target.function_group,
98	  });
99	  if (type === 'CLAS/OC') {
100	    const part = (target.class_include ?? 'main').toLowerCase();
101	    if (!(CLASS_INCLUDES as readonly string[]).includes(part)) {
102	      throw new Error(
103	        `class_include must be one of ${CLASS_INCLUDES.join(', ')}`,
104	      );
105	    }
106	    return `${base}/includes/${part}/versions`;
107	  }
108	  return `${base}/source/main/versions`;
109	}
110	
111	const asArray = <T>(v: T | T[] | undefined): T[] =>
112	  v === undefined ? [] : Array.isArray(v) ? v : [v];
113	const text = (v: unknown): string =>
114	  v === undefined || v === null
115	    ? ''
116	    : typeof v === 'object'
117	      ? String((v as Record<string, unknown>)['#text'] ?? '')
118	      : String(v);
119	
120	/** Strips the host from an absolute URI, so the request goes through the same connection. */
121	export function adtPath(uri: string): string {
122	  if (!/^https?:/i.test(uri)) return uri;
123	  try {
124	    const u = new URL(uri);
125	    return `${u.pathname}${u.search}`;
126	  } catch {
127	    return uri;
128	  }
129	}
130	
131	/**
132	 * Parses the ADT revision feed into versions, newest first as SAP sends them.
133	 * Tolerant: an entry without a content link is kept with an empty content_uri.
134	 */
135	export function parseVersionsFeed(xml: string): ObjectVersion[] {
136	  const parser = new XMLParser({
137	    ignoreAttributes: false,
138	    attributeNamePrefix: '',
139	    removeNSPrefix: true,
140	  });
141	  const doc = parser.parse(String(xml ?? ''));
142	  const entries = asArray(doc?.feed?.entry);
143	  return entries.map((e: any) => {
144	    const links = asArray<any>(e.link);
145	    const contentLink =
146	      (e.content && typeof e.content === 'object' && e.content.src) ||
147	      links.find(
148	        (l) =>
149	          /relations\/content$|\/content$/.test(String(l.rel ?? '')) ||
150	          /\/content$/.test(String(l.href ?? '')),
151	      )?.href ||
152	      '';
153	    const trLink = links.find((l) => /transport/i.test(String(l.rel ?? '')));
154	    // content URI: …/versions/<yyyymmddhhmmss>/<version no>/content
155	    const m = /\/versions\/[^/]+\/(\d+)\/content/.exec(String(contentLink));
156	    return {
157	      version: m?.[1] ?? text(e.id).split('/').pop() ?? '',
158	      date: text(e.updated),
159	      author: text(e.author?.name ?? e.author),
160	      transport: String(trLink?.name ?? trLink?.title ?? '').trim(),
161	      title: text(e.title),
