export const TOOL_DEFINITION = {
  name: 'GetObjectVersionSource',
  available_in: ['onprem'] as const,
  description:
    '[read-only] Read the source of one earlier version of an ABAP object. Pass the content_uri from GetObjectVersions, or the object plus its version number (the version list is read first). Compare it with the current source (GetProgram / GetClass …) to see what a transport changed.',
  inputSchema: {
    type: 'object',
    properties: {
      content_uri: {
        type: 'string',
        description:
          'content_uri of a version from GetObjectVersions (wins over the object fields).',
      },
      object_type: {
        type: 'string',
        description:
          'PROG/P, PROG/I, CLAS/OC, INTF/OI or FUGR/FF (with version).',
      },
      object_name: {
        type: 'string',
        description: 'Object name (with version).',
      },
      function_group: {
        type: 'string',
        description: 'Function group of a function module.',
      },
      class_include: {
        type: 'string',
        enum: [...CLASS_INCLUDES],
        description: 'Class part (default main).',
      },
      version: {
        type: 'string',
        description: 'Version number as listed, e.g. 00003 or 3.',
      },
    },
  },
} as const;

/**
 * Returns the source text of one version.
 * @param args content_uri, or object_type + object_name (+ function_group / class_include) + version
 */
export async function handleGetObjectVersionSource(
  context: HandlerContext,
  args: any,
) {
  const { connection } = context;
  try {
    let uri = String(args?.content_uri ?? '').trim();
    let meta: Record<string, unknown> = {};
    if (!uri) {
      const version = String(args?.version ?? '').trim();
      if (!args?.object_type || !args?.object_name || !version) {
